const lookupArtifacts = `-- name: LookupArtifacts :many
SELECT a.id, a.type, a.name, a.group_name
FROM artifact a
WHERE a.name = $1::text
  AND ($2::text IS NULL OR a.type = $2)
  AND ($3::text IS NULL OR COALESCE(a.group_name, '') = $3)
  AND artifact_visible(a.id, $4::uuid, $5::boolean)
ORDER BY a.type, a.group_name NULLS FIRST, a.id
LIMIT 50
`

type LookupArtifactsParams struct {
	Name      string      `json:"name"`
	Type      pgtype.Text `json:"type"`
	GroupName pgtype.Text `json:"group_name"`
	UserID    pgtype.UUID `json:"user_id"`
	IsAdmin   pgtype.Bool `json:"is_admin"`
}

type LookupArtifactsRow struct {
	ID        pgtype.UUID `json:"id"`
	Type      string      `json:"type"`
	Name      string      `json:"name"`
	GroupName pgtype.Text `json:"group_name"`
}

// ADR-042 R3/R4: name-keyed resolver. Unlike ListArtifacts, `name` here is an
// exact key, not an ILIKE search — the resolver's contract is unique-or-409,
// so a substring match would make ambiguity the normal case. `type` and
// `group_name` are the R4 ladder rungs; NULL means wildcard, not an
// empty-string match, so omitting a qualifier widens the query rather than
// pinning it to rows with an empty value.
//
// R5: artifact_visible() is applied here so the caller counts only visible
// candidates. A private artifact must not turn a unique public match into a
// 409 — that would leak its existence.
func (q *Queries) LookupArtifacts(ctx context.Context, arg LookupArtifactsParams) ([]LookupArtifactsRow, error) {
	rows, err := q.db.Query(ctx, lookupArtifacts,
		arg.Name,
		arg.Type,
		arg.GroupName,
		arg.UserID,
		arg.IsAdmin,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LookupArtifactsRow{}
	for rows.Next() {
		var i LookupArtifactsRow
		if err := rows.Scan(
			&i.ID,
			&i.Type,
			&i.Name,
			&i.GroupName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const unlinkArtifactNamespaces = `-- name: UnlinkArtifactNamespaces :exec
DELETE FROM artifact_namespace
WHERE artifact_id = $1::uuid
  AND namespace_id = ANY ($2::uuid[])
`

type UnlinkArtifactNamespacesParams struct {
	ArtifactID   pgtype.UUID   `json:"artifact_id"`
	NamespaceIds []pgtype.UUID `json:"namespace_ids"`
}

func (q *Queries) UnlinkArtifactNamespaces(ctx context.Context, arg UnlinkArtifactNamespacesParams) error {
	_, err := q.db.Exec(ctx, unlinkArtifactNamespaces, arg.ArtifactID, arg.NamespaceIds)
	return err
}

const upsertArtifact = `-- name: UpsertArtifact :one
INSERT INTO artifact (type, name, group_name, purl, cpe)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (type, name, COALESCE(group_name, ''))
DO UPDATE SET
    purl = COALESCE(EXCLUDED.purl, artifact.purl),
    cpe  = COALESCE(EXCLUDED.cpe, artifact.cpe)
WHERE EXISTS (
          SELECT 1 FROM artifact_namespace an
          WHERE an.artifact_id = artifact.id
            AND an.namespace_id = $6::uuid)
   OR NOT EXISTS (
          SELECT 1 FROM artifact_namespace an
          WHERE an.artifact_id = artifact.id)
RETURNING id
`

type UpsertArtifactParams struct {
	Type        string      `json:"type"`
	Name        string      `json:"name"`
	GroupName   pgtype.Text `json:"group_name"`
	Purl        pgtype.Text `json:"purl"`
	Cpe         pgtype.Text `json:"cpe"`
	NamespaceID pgtype.UUID `json:"namespace_id"`
}

// The artifact row is shared by name across namespaces, so its purl and cpe are
// only rewritten by an ingest into a namespace that already holds the artifact
// (or when no namespace holds it). Any other namespace's ingest leaves them as
// they are: the conflict arm updates nothing and RETURNING yields no row, which
// the caller answers by reading the existing id.
func (q *Queries) UpsertArtifact(ctx context.Context, arg UpsertArtifactParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, upsertArtifact,
		arg.Type,
		arg.Name,
		arg.GroupName,
		arg.Purl,
		arg.Cpe,
		arg.NamespaceID,
	)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

const upsertArtifactNamespace = `-- name: UpsertArtifactNamespace :exec
INSERT INTO artifact_namespace (artifact_id, namespace_id)
VALUES ($1, $2)
ON CONFLICT DO NOTHING
`

type UpsertArtifactNamespaceParams struct {
	ArtifactID  pgtype.UUID `json:"artifact_id"`
	NamespaceID pgtype.UUID `json:"namespace_id"`
}

func (q *Queries) UpsertArtifactNamespace(ctx context.Context, arg UpsertArtifactNamespaceParams) error {
	_, err := q.db.Exec(ctx, upsertArtifactNamespace, arg.ArtifactID, arg.NamespaceID)
	return err
}
